#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--){
        int n,k;
        cin >> n >> k;
        string s;
        cin >> s;
        int l=0,r=0;
        bool flag=false;
        
        for(int i=0;i<n;++i){
            if(s[i]=='G'&&l<=k){
                l++;
            }else if(s[i]=='G' && l>k){
                flag=true;
                r++;
            }else if(s[i]=='I' && flag==true){
                r+=2;
            }
        }
        
        if(r>k){
            cout << "NO" << "\n";
        }else{
            cout << "YES" << "\n";
        }
    }
}
